import {privateJson} from './session.js';
import {validateZone,zoneAt,zoneClock,parseZonePace,zoneRange,zoneDate} from './zone-model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountZoneSettings(root){
 let pack,kind=new URLSearchParams(location.search).get('zones')==='pace'?'pace':'heart',editing=false,busy=false,status='',drafts={},operations={};
 const title=()=>kind==='heart'?'Heart rate':'Pace';
 const latest=()=>pack.versions.filter(v=>v.kind===kind).toSorted((a,b)=>b.revision-a.revision)[0];
 function remember(){const form=root.querySelector('form');if(!form)return;const f=new FormData(form);const next={effectiveFrom:f.get('effectiveFrom'),source:f.get('source'),enabled:f.get('enabled')==='yes',values:[...form.querySelectorAll('[data-boundary]')].map(e=>e.value),expectedRevision:Number(form.dataset.revision)};if(JSON.stringify(next)!==JSON.stringify(drafts[kind]))delete operations[kind];drafts[kind]=next;}
 function render(){
  const saved=latest(),active=zoneAt(pack.versions,kind,pack.today),draft=drafts[kind]||{effectiveFrom:pack.today,source:active?.source||saved?.source||'',enabled:active?Boolean(active.boundaries):true,values:(active?.boundaries||saved?.boundaries||[]).map(v=>kind==='heart'?String(v):zoneClock(v)),expectedRevision:saved?.revision||0};
  root.innerHTML=`<div class="zn-heading"><div><h2>Your running zones</h2><p>Make the effort personal.</p></div><a href="/training?view=progress&zone=${kind}#personal-zones">View progress</a></div><div class="zn-tabs" role="group" aria-label="Zone measurement">${[['heart','Heart rate'],['pace','Pace']].map(([k,l])=>`<button type="button" data-zone-kind="${k}" aria-pressed="${kind===k}" ${busy?'disabled':''}>${l}</button>`).join('')}</div>${editing?`<form class="zn-form" novalidate data-revision="${draft.expectedRevision}"><fieldset ${busy?'disabled':''}><legend class="sr-only">${title()} zone settings</legend><div class="zn-form-top"><label>Effective from<input type="date" name="effectiveFrom" min="2026-07-01" max="${pack.today}" value="${esc(draft.effectiveFrom)}" required></label><label>Settings source<select name="source" required><option value="">Choose a source</option>${[['garmin','Garmin Connect'],['coach','Your coach'],['manual','Your own settings']].map(([v,l])=>`<option value="${v}" ${draft.source===v?'selected':''}>${l}</option>`).join('')}</select></label></div><p class="zn-help">Applies to runs on or after this date. Choose an earlier date to include past runs.</p><div class="zn-mode"><label><input type="radio" name="enabled" value="yes" ${draft.enabled?'checked':''}>Use personal zones</label><label><input type="radio" name="enabled" value="no" ${!draft.enabled?'checked':''}>Use recorded ranges</label></div><div class="zn-boundaries" ${!draft.enabled?'hidden':''}><p>${kind==='heart'?'Enter the heart rate where each zone starts.':'Enter the pace where each zone starts. Higher zones must be faster.'}</p>${Array.from({length:kind==='heart'?4:5},(_,i)=>`<label><span>Zone ${i+2} starts at</span><span class="zn-input-unit"><input data-boundary="${i}" id="zone-boundary-${i}" name="boundary${i}" type="text" inputmode="${kind==='heart'?'numeric':'text'}" autocomplete="off" maxlength="${kind==='heart'?3:5}" value="${esc(draft.values[i]||'')}" aria-label="Zone ${i+2} starts at, ${kind==='heart'?'beats per minute':'minutes and seconds per kilometre'}"><span>${kind==='heart'?'bpm':'/km'}</span></span></label>`).join('')}<p class="zn-help">${kind==='heart'?'Whole bpm · for example, the lower boundary shown in Garmin.':'Use m:ss, such as 6:30. These are your own pace settings.'}</p></div><div class="zn-actions"><button class="primary-button" type="submit">${busy?'Saving…':'Save zones'}</button><button class="text-button" type="button" data-zone-cancel>Cancel</button></div></fieldset><p id="zone-settings-status" class="zn-status" role="status">${esc(status)}</p><button class="text-button" type="button" data-zone-reload hidden>Reload saved settings</button></form>`:`${active?.boundaries?`<div class="zn-saved"><p>${title()} · effective ${esc(zoneDate(active.effectiveFrom))}</p><div class="zn-range-list">${Array.from({length:active.boundaries.length+1},(_,i)=>`<div><strong>Z${i+1}</strong><span>${esc(zoneRange(active,i))}${kind==='heart'?' bpm':' /km'}</span></div>`).join('')}</div></div>`:`<p class="zn-empty">${active?`Personal ${title().toLowerCase()} zones are off. Recorded ranges apply from ${esc(zoneDate(active.effectiveFrom))}.`:`${title()} zones aren’t set yet. Enter your Garmin or coach’s boundaries to see time in your own zones.`}</p>`}<button type="button" class="secondary-button" data-zone-edit>${active?'Edit '+title().toLowerCase()+' zones':'Set '+title().toLowerCase()+' zones'}</button><p class="zn-status" role="status">${esc(status)}</p>`}${pack.versions.some(v=>v.kind===kind)?`<details class="zn-history"><summary>Settings history</summary><ol>${pack.versions.filter(v=>v.kind===kind).toSorted((a,b)=>b.revision-a.revision).map(v=>`<li><span>v${v.revision} · ${esc(zoneDate(v.effectiveFrom))}</span><span>${v.boundaries?'Personal zones':'Recorded ranges'} · ${esc({garmin:'Garmin',coach:'Coach',manual:'Your settings'}[v.source])}</span></li>`).join('')}</ol><p>Earlier versions stay saved. Each run uses the latest version effective on its date.</p></details>`:''}`;
  root.querySelectorAll('[data-zone-kind]').forEach(b=>b.addEventListener('click',()=>{if(busy)return;remember();kind=b.dataset.zoneKind;status='';render();root.querySelector(`[data-zone-kind="${kind}"]`).focus();}));
  root.querySelector('[data-zone-edit]')?.addEventListener('click',()=>{editing=true;status='';render();root.querySelector('input').focus({preventScroll:true});});
  root.querySelector('[data-zone-cancel]')?.addEventListener('click',()=>{delete drafts[kind];editing=false;delete operations[kind];status='';render();root.querySelector('[data-zone-edit]').focus({preventScroll:true});});
  const form=root.querySelector('form');form?.addEventListener('input',()=>{form.querySelectorAll('[aria-invalid]').forEach(el=>{el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby');});remember();form.querySelector('.zn-boundaries').hidden=form.querySelector('[name=enabled]:checked').value==='no';});
  function lock(value){root.querySelectorAll('[data-zone-kind],[data-zone-reload]').forEach(b=>b.disabled=value);const fields=root.querySelector('fieldset');if(fields)fields.disabled=value;}
  root.querySelector('[data-zone-reload]')?.addEventListener('click',async()=>{if(busy)return;busy=true;const reloadKind=kind;lock(true);try{pack=await privateJson('/api/private?route=zones');delete drafts[reloadKind];delete operations[reloadKind];status='Saved settings reloaded. Review them before saving.';busy=false;render();}catch(e){busy=false;lock(false);root.querySelector('.zn-status').textContent=e.message;}});
  form?.addEventListener('submit',async e=>{
   e.preventDefault();if(busy)return;remember();const d=drafts[kind];let value;
   try{value=validateZone({kind,effectiveFrom:d.effectiveFrom,source:d.source,boundaries:d.enabled?d.values.map(v=>kind==='heart'?/^[0-9]+$/.test(v)?Number(v):NaN:parseZonePace(v)):null},pack.today);}catch(e){const out=form.querySelector('.zn-status');out.textContent=e.message;out.setAttribute('role','alert');let field=!d.source?form.querySelector('[name=source]'):!form.querySelector('[name=effectiveFrom]').validity.valid?form.querySelector('[name=effectiveFrom]'):null;const inputs=[...form.querySelectorAll('[data-boundary]')],values=d.values.map(v=>kind==='heart'?/^[0-9]+$/.test(v)?Number(v):NaN:parseZonePace(v));field??=inputs.find((input,i)=>!Number.isInteger(values[i])||values[i]<(kind==='heart'?40:60)||values[i]>(kind==='heart'?240:3600)||i>0&&(kind==='heart'?values[i]<=values[i-1]:values[i]>=values[i-1]))||form.querySelector('[name=effectiveFrom]');field.setAttribute('aria-invalid','true');field.setAttribute('aria-describedby','zone-settings-status');field.focus();return;}
   operations[kind]??=crypto.randomUUID();const body={...value,expectedRevision:d.expectedRevision,operationId:operations[kind]};busy=true;status='Saving your settings…';const submit=form.querySelector('[type=submit]');submit.textContent='Saving…';lock(true);
   try{pack=await privateJson('/api/private?route=zones',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});delete drafts[kind];editing=false;status=title()+' settings saved from '+zoneDate(value.effectiveFrom)+'.';delete operations[kind];busy=false;render();root.querySelector('[data-zone-edit]').focus({preventScroll:true});}
   catch(e){busy=false;lock(false);submit.textContent='Save zones';form.querySelector('.zn-status').textContent=e.message;form.querySelector('.zn-status').setAttribute('role','alert');form.querySelector('[data-zone-reload]').hidden=e.status!==409;}
  });
 }
 root.innerHTML='<h2>Your running zones</h2><p role="status">Opening your settings…</p>';
 try{pack=await privateJson('/api/private?route=zones');render();if(location.hash==='#running-zones')root.scrollIntoView({block:'start'});}catch(e){root.innerHTML=`<h2>Your running zones</h2><p role="status">${esc(e.message)}</p><button type="button" class="secondary-button">Retry settings</button>`;root.querySelector('button').addEventListener('click',()=>void mountZoneSettings(root));}
}
